void bfs_order(int V, const std::vector<std::vector<int>>& adj, int start, std::vector<int>& out) {
    std::vector<int> visited(V, 0);
    std::queue<int> q;
    q.push(start);
    visited[start] = 1;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        out.push_back(u);
        for (size_t i = 0; i < adj[u].size(); i++) {
            int v = adj[u][i];
            if (!visited[v]) {
                visited[v] = 1;
                q.push(v);
            }
        }
    }
}

